  const LEVELS = {1:'Базовый',2:'Средний',3:'Сложный'};
  function rng(seed){let s=seed>>>0;return {next(){s=(Math.imul(1664525,s)+1013904223)>>>0;return s/4294967296},int(a,b){return a+Math.floor(this.next()*(b-a+1))},pick(a){return a[this.int(0,a.length-1)]}}}
  function sign(n){return n<0?' − '+Math.abs(n):' + '+n}
  function num(v){return Number.isInteger(v)?String(v):String(Number(v.toFixed(5)))}
  function formulaQuadratic(a,h,k){return 'y = '+(a===1?'':a===-1?'−':num(a))+'(x'+(h<0?' + '+(-h):h>0?' − '+h:'')+')²'+(k===0?'':sign(k))}
  function formulaLine(m,b){return 'y = '+(m===1?'x':m===-1?'−x':num(m)+'x')+(b===0?'':sign(b))}
  function F(fn,label,color){return {fn,label:label||'',color:color||'main'}}
  function plot(functions,extra){return Object.assign({xMin:-8,xMax:8,yMin:-8,yMax:8,functions,holes:[],points:[],horizontal:[],vertical:[]},extra||{})}
