  function makeTask(templateId,seed){if(templateId.startsWith('og-line-match-'))seed=0;const t=TEMPLATES.find(t=>t.id===templateId);if(!t)throw Error('Unknown template: '+templateId);const o=t.make(rng(seed));return Object.assign({id:t.id,exam:t.exam,level:t.level,topic:t.topic,seed,format:'number',answer:null,chart:plot([])},o)}
  function parseAnswer(value){if(typeof value==='number')return Number.isFinite(value)?value:null;const s=String(value||'').trim().replace(/−/g,'-').replace(',','.').replace(/\s+/g,'');if(!s)return null;const fraction=s.match(/^([+-]?\d+(?:\.\d+)?)\/([+-]?\d+(?:\.\d+)?)$/);if(fraction){const denominator=Number(fraction[2]);return denominator===0?null:Number(fraction[1])/denominator}if(!/^[+-]?(\d+\.?\d*|\.\d+)$/.test(s))return null;const n=Number(s);return Number.isFinite(n)?n:null}
