  function topicsForExam(){return [...new Set(TEMPLATES.filter(t=>t.exam===ui.exam).map(t=>t.topic))]}
  function activeTemplates(){return TEMPLATES.filter(t=>t.exam===ui.exam&&(ui.level==='all'||t.level===Number(ui.level))&&(ui.topic==='all'||t.topic===ui.topic))}
