  function nextTask(){const pool=activeTemplates();if(!pool.length){ui.current=null;return}if(ui.queue.length===0){ui.queue=pool.map(t=>t.id).sort(()=>Math.random()-.5);if(ui.queue.length>1&&ui.current&&ui.queue[0]===ui.current.id)ui.queue.push(ui.queue.shift())}const id=ui.queue.shift();ui.current=makeTask(id,id.startsWith('og-line-match-')?0:Math.floor(Math.random()*2147483647));resetTaskState()}
